  ('1690f46a-8e4d-4c4c-b9a9-867dac965481', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', null, 'topic'::public.curated_course_node_type, 'Circuit Elements and Electrical Quantities', 'This opening section gives students the vocabulary of circuits: what voltage, current, resistance, capacitance, inductance, and power mean physically and mathematically.', 0),
  ('21750dda-3b61-4465-b73f-2cbe5988c24a', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '1690f46a-8e4d-4c4c-b9a9-867dac965481', 'subtopic'::public.curated_course_node_type, 'Voltage, Current, Charge, and Power', 'These quantities are the language used to describe what a circuit is doing and whether energy is being stored, delivered, or dissipated.', 0),
