  ('a2cc30c7-17cc-4c67-b029-0b81f605e36c', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', null, 'topic'::public.curated_course_node_type, 'Ohm''s Law and Kirchhoff''s Laws', 'Circuit analysis rests on local component laws plus network conservation laws. This section turns circuit diagrams into solvable equations.', 1),
