  ('638911c3-ba70-4b3e-b541-955fed469262', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', null, 'topic'::public.curated_course_node_type, 'Resistive Circuit Analysis', 'Before adding dynamics and AC behavior, students need fluency with resistive networks, equivalent resistance, and source/load interactions.', 2),
