  ('351d6532-c1cc-43cd-8ae5-838a859d28ba', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'ee92c1cf-3d23-46c6-87bd-a0c92e2775f7', 'concept'::public.curated_course_node_type, 'Sensor and bias examples', null, 2),
  ('7dea56ce-ea29-48e8-8372-7d5a0697390f', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '638911c3-ba70-4b3e-b541-955fed469262', 'subtopic'::public.curated_course_node_type, 'Dependent-Source Circuits', 'Dependent sources model amplifiers and controlled behavior, so they prepare students for op-amps and electronics.', 2),
  ('8bec1f3b-643c-4406-ad68-3da5c614d355', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '7dea56ce-ea29-48e8-8372-7d5a0697390f', 'concept'::public.curated_course_node_type, 'Voltage-controlled sources', null, 0),
  ('225bf415-a58e-4df3-82be-827268038f5a', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '7dea56ce-ea29-48e8-8372-7d5a0697390f', 'concept'::public.curated_course_node_type, 'Current-controlled sources', null, 1),
  ('03bdf8a1-1aba-4a76-a2db-019af98826af', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '7dea56ce-ea29-48e8-8372-7d5a0697390f', 'concept'::public.curated_course_node_type, 'Test-source methods', null, 2),
  ('cd48e50a-6fca-4c18-93ab-1fc24a4aa0aa', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '638911c3-ba70-4b3e-b541-955fed469262', 'subtopic'::public.curated_course_node_type, 'Linearity and Superposition', 'Superposition lets students separate source contributions in linear circuits.', 3),
