  ('edf04ede-875c-4bbd-ac6a-3db09b4b4a6c', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'cd48e50a-6fca-4c18-93ab-1fc24a4aa0aa', 'concept'::public.curated_course_node_type, 'Handling dependent sources', null, 1),
  ('1e9b5e4f-bb36-4eea-a639-d3bb688bbf67', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'cd48e50a-6fca-4c18-93ab-1fc24a4aa0aa', 'concept'::public.curated_course_node_type, 'Power is not superposed directly', null, 2),
  ('58fa0a96-3886-4271-8c02-5fa624050b66', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', null, 'topic'::public.curated_course_node_type, 'Nodal and Mesh Analysis', 'Nodal and mesh methods are systematic equation-building techniques. They replace guesswork with repeatable procedures for circuits that cannot be simplified by inspection.', 3),
  ('17aac741-c323-4f0d-bf57-278428c29b86', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '58fa0a96-3886-4271-8c02-5fa624050b66', 'subtopic'::public.curated_course_node_type, 'Nodal Analysis', 'Nodal analysis solves for node voltages using KCL and is usually the most general method for circuit work.', 0),
  ('442d0db4-9b16-4be8-8047-2590b7677fd4', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '17aac741-c323-4f0d-bf57-278428c29b86', 'concept'::public.curated_course_node_type, 'Reference node selection', null, 0),
  ('294c3aa6-5a61-4897-a80d-8536f15b2ff1', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '17aac741-c323-4f0d-bf57-278428c29b86', 'concept'::public.curated_course_node_type, 'Conductance form', null, 1),
  ('23513837-052b-416e-8d83-f290b66a7fc7', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '17aac741-c323-4f0d-bf57-278428c29b86', 'concept'::public.curated_course_node_type, 'Current-source handling', null, 2),
  ('a8eda26b-615b-4aa0-8689-c4339f42a84b', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '58fa0a96-3886-4271-8c02-5fa624050b66', 'subtopic'::public.curated_course_node_type, 'Supernodes', 'Supernodes handle voltage sources between non-reference nodes without breaking KCL logic.', 1),
  ('a5ceaadd-9376-401c-a2c7-8d7f14dc53a8', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'a8eda26b-615b-4aa0-8689-c4339f42a84b', 'concept'::public.curated_course_node_type, 'Voltage constraints', null, 0),
