  ('c8876db9-6194-41ac-a8c3-8e189b1a3304', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'a8eda26b-615b-4aa0-8689-c4339f42a84b', 'concept'::public.curated_course_node_type, 'Dependent-source cases', null, 2),
