  ('ae21231c-ae8b-446e-8e4c-2be2afa0fb9c', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'b5e38c8a-dae7-423c-8e82-0a2f64302359', 'concept'::public.curated_course_node_type, 'Mesh-current definitions', null, 0),
  ('3f92cf80-1fc4-4145-babd-35473a12f249', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'b5e38c8a-dae7-423c-8e82-0a2f64302359', 'concept'::public.curated_course_node_type, 'Shared-element voltages', null, 1),
  ('86af85eb-bbf4-4762-8f50-6e9a107d08c9', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'b5e38c8a-dae7-423c-8e82-0a2f64302359', 'concept'::public.curated_course_node_type, 'Voltage-source handling', null, 2),
