  ('461ba089-61f6-4dc9-8e7b-75fbfa54dc16', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'fa4db94b-83fe-4a03-89de-f869898887b6', 'concept'::public.curated_course_node_type, 'Current-source constraints', null, 0),
