  ('3c64aabf-d812-4471-a436-0e766cb52359', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', 'fa4db94b-83fe-4a03-89de-f869898887b6', 'concept'::public.curated_course_node_type, 'Nodal versus mesh tradeoffs', null, 2),
