  ('30288d39-c6be-4cbf-861d-0a79bebe9720', 'ffd99283-cd24-46fc-acc7-b3346f0d3a95', '34d5f77a-e3e5-47a8-8cf8-43dd6f78c8d8', 'concept'::public.curated_course_node_type, 'Open-circuit voltage', null, 0),
